package maelstrom

import (
	"encoding/json"
	"errors"
	"fmt"
)

// RPC error code constants.
const (
	Timeout                = 0
	NotSupported           = 10
	TemporarilyUnavailable = 11
	MalformedRequest       = 12
	Crash                  = 13
	Abort                  = 14
	KeyDoesNotExist        = 20
	KeyAlreadyExists       = 21
	PreconditionFailed     = 22
	TxnConflict            = 30
)

// ErrorCodeText returns the text representation of an error code.
func ErrorCodeText(code int) string {
	switch code {
	case Timeout:
		return "Timeout"
	case NotSupported:
		return "NotSupported"
	case TemporarilyUnavailable:
		return "TemporarilyUnavailable"
	case MalformedRequest:
		return "MalformedRequest"
	case Crash:
		return "Crash"
	case Abort:
		return "Abort"
	case KeyDoesNotExist:
		return "KeyDoesNotExist"
	case KeyAlreadyExists:
		return "KeyAlreadyExists"
	case PreconditionFailed:
		return "PreconditionFailed"
	case TxnConflict:
		return "TxnConflict"
	default:
		return fmt.Sprintf("ErrorCode<%d>", code)
	}
}

// ErrorCode returns the error code from err. Returns -1 if err does not have an *RPCError.
func ErrorCode(err error) int {
	var rpc *RPCError
	if errors.As(err, &rpc) {
		return rpc.Code
	}
	return -1
}

// RPCError represents a Maelstrom RPC error.
type RPCError struct {
	Code int
	Text string
}

// NewRPCError returns a new instance of RPCError.
func NewRPCError(code int, text string) *RPCError {
	return &RPCError{
		Code: code,
		Text: text,
	}
}

// Error returns a string-formatted error message.
func (e *RPCError) Error() string {
	return fmt.Sprintf("RPCError(%s, %q)", ErrorCodeText(e.Code), e.Text)
}

// MarshalJSON marshals the error into JSON format.
func (e *RPCError) MarshalJSON() ([]byte, error) {
	return json.Marshal(rpcErrorJSON{
		Type: "error",
		Code: e.Code,
		Text: e.Text,
	})
}

// rpcErrorJSON is a struct for marshaling an RPCError to JSON.
type rpcErrorJSON struct {
	Type string `json:"type,omitempty"`
	Code int    `json:"code,omitempty"`
	Text string `json:"text,omitempty"`
}

package maelstrom_test

import (
	"context"
	"errors"
	"testing"
	"time"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func TestKVReadStruct(t *testing.T) {
	type testPayload struct {
		Counter int
	}
	t.Run("OK", func(t *testing.T) {
		n, stdin, stdout := newNode(t)
		kv := maelstrom.NewSeqKV(n)
		initNode(t, n, "n1", []string{"n1"}, stdin, stdout)

		respCh := make(chan testPayload)
		errorCh := make(chan error)
		go func() {
			var p testPayload
			err := kv.ReadInto(context.Background(), "foo", &p)
			if err != nil {
				errorCh <- err
				return
			}
			respCh <- p
		}()

		// Ensure RPC request is received by the network.
		if line, err := stdout.ReadString('\n'); err != nil {
			t.Fatal(err)
		} else if got, want := line, `{"src":"n1","dest":"seq-kv","body":{"key":"foo","msg_id":1,"type":"read"}}`+"\n"; got != want {
			t.Fatalf("response=%s, want %s", got, want)
		}

		// Write response message back to node.
		if _, err := stdin.Write([]byte(`{"src":"seq-kv","dest":"n1","body":{"type":"read_ok","value":{"Counter":13},"msg_id":2,"in_reply_to":1}}` + "\n")); err != nil {
			t.Fatal(err)
		}

		select {
		case p := <-respCh:
			if got, want := p.Counter, 13; got != want {
				t.Fatalf("counter=%d, want %d", got, want)
			}
		case err := <-errorCh:
			t.Fatal(err)
		case <-time.After(5 * time.Second):
			t.Fatal("timeout waiting for RPC response")
		}
	})
	t.Run("RPCError", func(t *testing.T) {
		n, stdin, stdout := newNode(t)
		kv := maelstrom.NewSeqKV(n)
		initNode(t, n, "n1", []string{"n1"}, stdin, stdout)

		errorCh := make(chan error)
		go func() {
			err := kv.ReadInto(context.Background(), "foo", nil)
			if err != nil {
				errorCh <- err
				return
			}
		}()

		// Ensure RPC request is received by the network.
		if line, err := stdout.ReadString('\n'); err != nil {
			t.Fatal(err)
		} else if got, want := line, `{"src":"n1","dest":"seq-kv","body":{"key":"foo","msg_id":1,"type":"read"}}`+"\n"; got != want {
			t.Fatalf("response=%s, want %s", got, want)
		}

		// Write response message back to node.
		if _, err := stdin.Write([]byte(`{"src":"seq-kv", "dest":"n1","body":{"type":"read_ok","code":20,"text":"key does not exist","msg_id":2,"in_reply_to":1}}` + "\n")); err != nil {
			t.Fatal(err)
		}

		// Ensure the response was received.
		select {
		case err := <-errorCh:
			var rpcError *maelstrom.RPCError
			if !errors.As(err, &rpcError) {
				t.Fatalf("unexpected error type: %#v", err)
			} else if got, want := rpcError.Code, 20; got != want {
				t.Fatalf("code=%v, want %v", got, want)
			} else if got, want := rpcError.Text, "key does not exist"; got != want {
				t.Fatalf("text=%v, want %v", got, want)
			}
		case <-time.After(5 * time.Second):
			t.Fatal("timeout waiting for RPC response")
		}
	})
}

#!/usr/bin/node

// A CRDT PN-counter
var node = require('./node');

class GCounter {
  // Takes a map of node names to the count on that node.
  constructor(counts) {
    this.counts = counts;
  }

  // Returns the effective value of the counter.
  value() {
    var total = 0;
    for (const node in this.counts) {
      total += this.counts[node];
    }
    return total;
  }

  // Merges another GCounter into this one
  merge(other) {
    const counts = {... this.counts};
    for (const node in other.counts) {
      if (counts[node] == undefined) {
        counts[node] = other.counts[node];
      } else {
        counts[node] = Math.max(this.counts[node], other.counts[node]);
      }
    }
    return new GCounter(counts);
  }

  // Convert to a JSON-serializable object
  toJSON() {
    return this.counts;
  }

  // Inflates a JSON-serialized object back into a fresh GCounter
  fromJSON(json) {
    return new GCounter(json);
  }

  // Increment by delta
  increment(node, delta) {
    var count = this.counts[node];
    if (count == undefined) {
      count = 0;
    }
    var counts = {... this.counts};
    counts[node] = count + delta;
    return new GCounter(counts);
  }
}

class PNCounter {
  // Takes an increment GCounter and a decrement GCounter
  constructor(plus, minus) {
    this.plus = plus;
    this.minus = minus;
  }

  // The effective value is all increments minus decrements
  value() {
    return this.plus.value() - this.minus.value();
  }

  // Merges another PNCounter into this one
  merge(other) {
    return new PNCounter(
      this.plus.merge(other.plus),
      this.minus.merge(other.minus)
    );
  }

  // Converts to a JSON-serializable object
  toJSON() {
    return {plus: this.plus, minus: this.minus};
  }

  // Inflates a JSON-serialized object back into a fresh PNCounter
  fromJSON(json) {
    return new PNCounter(
      this.plus.fromJSON(json.plus),
      this.minus.fromJSON(json.minus)
    );
  }

  // Increment by delta
  increment(node, delta) {
    if (0 < delta) {
      return new PNCounter(this.plus.increment(node, delta), this.minus);
    } else {
      return new PNCounter(this.plus, this.minus.increment(node, delta * -1));
    }
  }
}

// Our CRDT state
var crdt = new PNCounter(new GCounter({}), new GCounter({}));

// Add new elements to our local state
node.on('add', function(req) {
  crdt = crdt.increment(node.nodeId(), req.body.delta);
  console.warn ("state after add:", crdt);
  node.reply(req, {type: 'add_ok'});
});

// When we get a read request, return our messages
node.on('read', function(req) {
  node.reply(req, {type: 'read_ok', value: crdt.value()});
});

// When we receive a replication message, merge it into our CRDT
node.on('replicate', (req) => {
  crdt = crdt.merge(crdt.fromJSON(req.body.value));
  console.warn("state after replicate:", crdt);
});

// When we initialize, start a replication loop
node.on('init', (req) => {
  setInterval(() => {
    console.warn('Replicate!');
    for (const peer of node.nodeIds()) {
      if (peer !== node.nodeId()) {
        node.send(peer, {type: 'replicate', value: crdt.toJSON()});
      }
    }
  }, 5000);
});

node.main();

